/* rf-scope trace records — the wire format shared by the halves (UART0), the
 * dongle (CDC) and the host tool (tools/rf_scope/rftrace/codec.py).
 *
 * Spec: docs/superpowers/specs/2026-10-20-rf-scope-design.md. PURE: no
 * ESP-IDF include, compiled as is in the host tests (test/test_rf_trace.c).
 * Shared vectors: docs/contracts/rf_trace_vectors.json, generated by
 * scripts/gen_rf_trace_vectors.sh and pinned by test_rf_trace_vectors.
 *
 * ── Framing: a KR frame of command 0xBA, not a new magic ─────────────────
 *
 *   [0x4B 'K'][0x52 'R'][0xBA][status 0x00][len:u16 LE]
 *   [version][kind][count][count × fixed-size record][crc8]
 *
 * CRC-8 = ks_crc8() over the payload (version..last record), exactly as for
 * every KR reply — the frame IS a KR reply, byte for byte what
 * ks_respond(0xBA, KS_STATUS_OK, payload, len) writes. Why reuse KR rather
 * than pick two fresh magic bytes:
 *
 *  - on the dongle the trace rides the CDC port, which is binary KS/KR only
 *    (CLAUDE.md): an unsolicited KR of a dedicated command is the protocol's
 *    own way to push data, the remapping software already skips KR frames it
 *    did not ask for, and the dongle can emit it with ks_respond();
 *  - on a half the SAME bytes go out on UART0, so the host keeps ONE parser
 *    for both ends, and tells trace frames from other KR replies by the
 *    command byte;
 *  - resync over console text: the console prints UTF-8 (ASCII plus French
 *    accents, arrows, box drawing). 0xBA is a UTF-8 continuation byte and
 *    can only follow a lead byte ≥ 0xC0 — never 'R'. "K R 0xBA" therefore
 *    NEVER occurs in valid console text. A candidate must then carry status
 *    0x00, version 1, a known kind, 1 ≤ count ≤ RF_TRACE_BATCH_MAX, a length
 *    equal to 3 + count × record size (checked from the 9-byte header,
 *    before waiting for the rest — a fake header never stalls the scanner),
 *    and finally the CRC. A candidate refused at any step advances the
 *    scanner by ONE byte, never by its claimed length: a fake header in
 *    binary noise must not swallow the real frame that starts inside it.
 *
 * ── Records: explicit little-endian byte encoding, no struct packing ─────
 *
 *   TX (13 B, a half, after each transmission in the radio owner)
 *     0 t_us u32 | 4 emitter | 5 seq | 6 pkt_kind | 7 payload_len | 8 result
 *     9 arc | 10 plos_delta | 11 channel | 12 flags (bit0 excursion)
 *   RX (13 B, the dongle, per frame read from the FIFO)
 *     0 t_us u32 | 4 emitter | 5 seq | 6 pkt_kind | 7 payload_len | 8 pipe
 *     9 rpd | 10 channel | 11 fifo_depth | 12 flags (bit0 delivered, bit1 dup)
 *   PERIODIC (20 B, both ends, ~1 Hz while tracing)
 *     0 t_us u32 | 4 uptime_s u32 | 8 source | 9 state | 10 batt_dV
 *     11 channel | 12 frames u16 | 14 fails u16 | 16 dups u16 | 18 drops u16
 *
 * t_us is the emitter's esp_timer, truncated to 32 bits (wraps every 71.6
 * min); the periodic uptime_s lets the host unwrap it. Unused flag bits must
 * be 0 on encode; decode keeps them (a newer emitter may set them).
 */
#ifndef RF_TRACE_H
#define RF_TRACE_H

#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

#define RF_TRACE_CMD            0xBAu  /* = KS_CMD_RF_TRACE (static-asserted in rf_trace.c) */
#define RF_TRACE_VERSION        1u
#define RF_TRACE_BATCH_MAX      16u    /* records per frame */

#define RF_TRACE_KIND_TX        1u
#define RF_TRACE_KIND_RX        2u
#define RF_TRACE_KIND_PERIODIC  3u

#define RF_TRACE_TX_SIZE        13u
#define RF_TRACE_RX_SIZE        13u
#define RF_TRACE_PERIODIC_SIZE  20u
#define RF_TRACE_REC_SIZE_MAX   20u

/* Header: K R cmd status len_lo len_hi | version kind count */
#define RF_TRACE_KR_HDR         6u
#define RF_TRACE_PAYLOAD_HDR    3u
#define RF_TRACE_HDR            (RF_TRACE_KR_HDR + RF_TRACE_PAYLOAD_HDR)   /* 9 */
#define RF_TRACE_FRAME_MAX      (RF_TRACE_HDR + RF_TRACE_BATCH_MAX * RF_TRACE_REC_SIZE_MAX + 1u)

/* Emitter / source identities. LEFT/RIGHT equal RF_HALF_LEFT/RIGHT. */
#define RF_TRACE_EMIT_LEFT      0u
#define RF_TRACE_EMIT_RIGHT     1u
#define RF_TRACE_EMIT_DONGLE    2u     /* periodic source only */
#define RF_TRACE_EMIT_MOUSE     3u     /* dongle slot 2 */

/* TX result */
#define RF_TRACE_TX_ACK         0u     /* TX_DS */
#define RF_TRACE_TX_MAX_RT      1u
#define RF_TRACE_TX_TIMEOUT     2u     /* neither flag came up */

#define RF_TRACE_TXF_EXCURSION  0x01u  /* left relay PRX→PTX→PRX */
#define RF_TRACE_RXF_DELIVERED  0x01u  /* consumed by the fusion engine */
#define RF_TRACE_RXF_DUP        0x02u  /* same (emitter, seq) already seen */

/* Periodic state */
#define RF_TRACE_ST_AWAKE       0u
#define RF_TRACE_ST_SLEEPING    1u     /* last record before a sleep */
#define RF_TRACE_ST_WOKE        2u     /* first record after a wake */

typedef struct {
    uint32_t t_us;
    uint8_t  emitter, seq, pkt_kind, payload_len;
    uint8_t  result, arc, plos_delta, channel, flags;
} rf_trace_tx_t;

typedef struct {
    uint32_t t_us;
    uint8_t  emitter, seq, pkt_kind, payload_len;
    uint8_t  pipe, rpd, channel, fifo_depth, flags;
} rf_trace_rx_t;

typedef struct {
    uint32_t t_us;
    uint32_t uptime_s;
    uint8_t  source, state, batt_dV, channel;
    uint16_t frames;   /* half: transmissions; dongle: frames read */
    uint16_t fails;    /* half: MAX_RT + timeouts; dongle: 0 */
    uint16_t dups;     /* dongle: duplicates; half: 0 */
    uint16_t drops;    /* ring overflow since the previous periodic record */
} rf_trace_periodic_t;

/* One ring slot: a tagged record. */
typedef struct {
    uint8_t kind;      /* RF_TRACE_KIND_* */
    union {
        rf_trace_tx_t       tx;
        rf_trace_rx_t       rx;
        rf_trace_periodic_t periodic;
    } u;
} rf_trace_rec_t;

typedef struct {
    uint8_t version;
    uint8_t kind;
    uint8_t count;
    rf_trace_rec_t rec[RF_TRACE_BATCH_MAX];   /* rec[i].kind == kind */
} rf_trace_frame_t;

typedef enum {
    RF_TRACE_OK = 0,
    RF_TRACE_ERR_ARG,        /* NULL pointer / output too small */
    RF_TRACE_ERR_SHORT,      /* fewer bytes than the header or the announced frame */
    RF_TRACE_ERR_MAGIC,      /* not 'K' 'R' */
    RF_TRACE_ERR_CMD,        /* KR frame, but not command 0xBA */
    RF_TRACE_ERR_STATUS,     /* status byte != 0 */
    RF_TRACE_ERR_VERSION,
    RF_TRACE_ERR_KIND,
    RF_TRACE_ERR_COUNT,      /* 0 or > RF_TRACE_BATCH_MAX */
    RF_TRACE_ERR_LEN,        /* len field != 3 + count × record size */
    RF_TRACE_ERR_CRC,
    RF_TRACE_ERR_TRAILING,   /* bytes after the CRC (decode takes ONE frame) */
} rf_trace_err_t;

const char *rf_trace_err_name(rf_trace_err_t e);

/* Record size of a kind, 0 for an unknown kind. */
size_t rf_trace_rec_size(uint8_t kind);

/* Fixed-size record codecs (out must hold rf_trace_rec_size(kind) bytes). */
void rf_trace_tx_encode(uint8_t *out, const rf_trace_tx_t *r);
void rf_trace_tx_decode(const uint8_t *in, rf_trace_tx_t *r);
void rf_trace_rx_encode(uint8_t *out, const rf_trace_rx_t *r);
void rf_trace_rx_decode(const uint8_t *in, rf_trace_rx_t *r);
void rf_trace_periodic_encode(uint8_t *out, const rf_trace_periodic_t *r);
void rf_trace_periodic_decode(const uint8_t *in, rf_trace_periodic_t *r);

/* Encodes a frame of `count` records, all of kind `kind` (rec[i].kind is
 * checked). Returns the frame length, 0 on error (bad kind, count 0 or >
 * BATCH_MAX, a record of another kind, cap too small). */
size_t rf_trace_frame_encode(uint8_t *out, size_t cap, uint8_t kind,
                             const rf_trace_rec_t *rec, size_t count);

/* Strict decode of exactly ONE frame occupying buf[0..len). */
rf_trace_err_t rf_trace_frame_decode(const uint8_t *buf, size_t len,
                                     rf_trace_frame_t *out);

/* Resync scanner over a byte stream with interleaved console text / noise.
 *   FOUND   — a valid frame at buf[*start .. *start + *flen); bytes before
 *             *start are not trace. Decoded into *out when out != NULL.
 *             Continue the scan at *start + *flen.
 *   PARTIAL — a plausible header (checked as far as the bytes go, a lone
 *             trailing 'K' included) begins at *start but the frame is
 *             incomplete: keep buf[*start..] and append more bytes.
 *   NONE    — no frame and no plausible beginning: *start = len, all of
 *             buf can be dropped. */
typedef enum {
    RF_TRACE_SCAN_NONE = 0,
    RF_TRACE_SCAN_FOUND,
    RF_TRACE_SCAN_PARTIAL,
} rf_trace_scan_t;

rf_trace_scan_t rf_trace_scan(const uint8_t *buf, size_t len,
                              size_t *start, size_t *flen,
                              rf_trace_frame_t *out);

/* ── Ring buffer: static storage owned by the caller ──────────────────────
 *
 * Single producer (radio owner / rx task) and single consumer (drain task).
 * push never blocks: on a full ring the record is dropped and counted.
 * head is written by the producer only, tail by the consumer only, and the
 * drop counter is split (produced/reported) so that read-and-reset from the
 * consumer never races with an increment from the producer. Indices are
 * free-running, the capacity must be a power of two. */
typedef struct {
    rf_trace_rec_t *slots;
    uint32_t cap;          /* power of two */
    uint32_t head;         /* producer */
    uint32_t tail;         /* consumer */
    uint32_t dropped;      /* producer: total drops */
    uint32_t drop_seen;    /* consumer: drops already reported */
} rf_trace_ring_t;

bool     rf_trace_ring_init(rf_trace_ring_t *r, rf_trace_rec_t *storage, uint32_t cap);
bool     rf_trace_ring_push(rf_trace_ring_t *r, const rf_trace_rec_t *rec);
uint32_t rf_trace_ring_count(const rf_trace_ring_t *r);
/* Pops up to `max` consecutive records of the SAME kind as the oldest one
 * (one frame's worth). Returns the number popped, 0 when empty. */
size_t   rf_trace_ring_pop_batch(rf_trace_ring_t *r, rf_trace_rec_t *out, size_t max);
/* Drops since the previous call (consumer side). */
uint32_t rf_trace_ring_drops_take(rf_trace_ring_t *r);

#endif /* RF_TRACE_H */
